import{_ as a,o as t,c as r,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Persistence and durable recovery","description":"","frontmatter":{"title":"Persistence and durable recovery","docId":"developer.storage","translationKey":"developer.storage","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","translationRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","order":60},"headers":[],"relativePath":"en/developer/storage.md","filePath":"en/developer/storage.md","lastUpdated":1794611623000}'),s={name:"en/developer/storage.md"};function o(n,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="persistence-and-durable-recovery" tabindex="-1">Persistence and durable recovery <a class="header-anchor" href="#persistence-and-durable-recovery" aria-label="Permalink to &quot;Persistence and durable recovery {#persistence-and-durable-recovery}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Change persistent state through its owning service and preserve recoverable outcomes. Use a disposable profile, close its host before copying databases and read <a href="./control-api.html">control metadata</a> before editing versioned resources. <code>TIKTOOLS_HOME</code> selects the application root; <code>AppPaths</code> resolves its data and private stores.</p><h2 id="identify-the-store" tabindex="-1">Identify the store <a class="header-anchor" href="#identify-the-store" aria-label="Permalink to &quot;Identify the store {#identify-the-store}&quot;">​</a></h2><p><code>crates/tiktools-core/src/paths.rs</code> defines <code>data/tiktok-points.db</code>, <code>data/tiktok-automation.db</code> and <code>data/tiktok-analytics.db</code>. SQLite service modules own their schemas. Points/viewers and automation definitions have separate business ledgers; analytics is a distinct database, which older two-database diagrams omit.</p><p>Startup can copy checkout-local legacy databases into platform app data only when a destination is absent. It never overwrites an existing destination. JSON definitions remain readable during native execution changes. Do not implement migration by deleting a user&#39;s profile or rewriting tables from Vue.</p><h2 id="make-a-recoverable-change" tabindex="-1">Make a recoverable change <a class="header-anchor" href="#make-a-recoverable-change" aria-label="Permalink to &quot;Make a recoverable change {#make-a-recoverable-change}&quot;">​</a></h2><ol><li>Locate the service transaction and its schema/migration tests.</li><li>Store the business change, revision and required journal/outbox reservation in the same transaction where that domain supports it.</li><li>Preserve revision tombstones on deletion. A reused record ID must not accept a pre-deletion edit revision.</li><li>Publish committed invalidation metadata through the existing outbox; a delivery retry must not repeat the underlying action.</li><li>Reopen the same private test home after interruption and resolve the original command before attempting another mutation.</li></ol><p>Useful read-only checks against an already running test host:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Supported durable workflow, points and owner journals retain original outcomes across restart. A receipt describes its historical command; read current state separately. Cloud workspace stores add origin/account partitions and generation checks; they do not replace the local SQLite authority. Not every external effect or domain has the same durable recovery coverage.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>Keep SQLite files and any active WAL/SHM together when making an offline backup. A UI timeout does not prove rollback. On <code>revision_conflict</code>, preserve the draft and compare a fresh read. On uncertain external effects, inspect the retained effect record rather than replaying a feed. See the <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/paths.rs" target="_blank" rel="noreferrer">path authority</a> and <a href="./cloud.html">Cloud recovery</a> for their distinct boundaries.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Resolve paths before experiments or backups with <code>tiktools api call system.info --json</code>. <code>TIKTOOLS_HOME</code> selects the root; independent <code>TIKTOOLS_DATA_DIR</code>, <code>TIKTOOLS_PLUGINS_DIR</code>, <code>TIKTOOLS_PLUGIN_DATA_DIR</code>, <code>TIKTOOLS_PLUGIN_STORE_DIR</code>, <code>TIKTOOLS_LOG_DIR</code> and <code>TIKTOOLS_TEMP_DIR</code> override their derived directories. Relative overrides resolve against the launching working directory. An isolated home alone does not neutralize inherited overrides; inspect/unset them first.</p><p>Analytics is aggregated data with a dedicated writer: current queue 1,024, batches 128, flush deadline 10 s. A sibling <code>*.pending.json</code> recovery file is derived from the analytics database path. Startup replays retained batches with IDs, then retires the file before <code>ready</code> admits new work. Unreadable/over-16-MiB recovery, unavailable database or failure to retire the file keeps admission disabled. Preserve the database and recovery file, inspect <code>ready</code>/pending/error diagnostics and back up before repair. Do not delete pending evidence to make startup appear healthy; points journals have a separate durability contract.</p><p><code>system.info</code> reports effective home/dataDir; resolve the other directories from the host’s actual launch environment, not an unrelated terminal. Use <code>system.health</code> for analytics ready/pending and LIVE ingress counters.</p>`,18)])])}const b=a(s,[["render",o]]);export{u as __pageData,b as default};
